select ,
       (select count(*)
        from inv_transfer_detail line
        where line.transfer_id = inv_transfer_order.transfer_id) detail_line_count
from inv_transfer_order

    and order_no like concat('%', #{orderNo}, '%')


            and status in

                #{item}



            and status = #{status}


    and transfer_type = #{transferType}
    and from_dept_id = #{fromDeptId}
    and to_dept_id = #{toDeptId}

        and status <> 'draft'


        and (from_dept_id = #{params.storeDeptId}
             or to_dept_id = #{params.storeDeptId})


        and not (
            transfer_type = 'cross_store'
            and status in ('draft', 'submitted')
            and from_dept_id = #{params.currentScopeDeptId}
            and to_dept_id <> #{params.currentScopeDeptId}
        )


        and (
            from_dept_id in #{deptId}
            or to_dept_id in #{deptId}
        )

    ${params.dataScope}

order by create_time desc

    limit #{params.rowLimit}


where source_business_type = #{sourceBusinessType}
  and source_business_id = #{sourceBusinessId}
  and from_warehouse_id = #{fromWarehouseId}
limit 1


where source_business_type = #{sourceBusinessType}
  and source_business_id = #{sourceBusinessId}
  and from_warehouse_id = #{fromWarehouseId}
limit 1 for update

mapper.update:
update inv_transfer_order
purchase_id = #{purchaseId}, from_dept_id = #{fromDeptId}, from_dept_name = #{fromDeptName}, from_warehouse_id = #{fromWarehouseId}, to_dept_id = #{toDeptId}, to_dept_name = #{toDeptName}, to_warehouse_id = #{toWarehouseId}, total_quantity = #{totalQuantity}, total_amount = #{totalAmount}, transfer_type = #{transferType}, return_reason_code = #{returnReasonCode}, return_reason_text = #{returnReasonText}, attachment_node_ids = #{attachmentNodeIds}, recipient_name = #{recipientName}, recipient_phone = #{recipientPhone}, shipping_address = #{shippingAddress}, source_business_type = #{sourceBusinessType}, source_business_id = #{sourceBusinessId}, source_confirm_status = #{sourceConfirmStatus}, reselection_from_transfer_id = #{reselectionFromTransferId}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate(), version = version + 1
where transfer_id = #{transferId} and status = 'draft' and version = #{version}

update inv_transfer_order
set approval_instance_id = #{instanceId},
    update_by = #{updateBy}, update_time = sysdate(),
    version = version + 1
where transfer_id = #{transferId}
  and status = 'submitted'
  and approval_engine = 'NATIVE'
  and approval_round = #{businessRound}
  and version = #{expectedVersion}
  and approval_instance_id is null

mapper.delete:
delete from inv_transfer_order
where transfer_id = #{transferId}
  and status = #{expectedStatus}
  and status in ('draft', 'cancelled')
  and coalesce(version, 0) = #{expectedVersion}
